    }

    receive() external payable {}

    function run(uint amount) public payable {
        require(amount > 0, "zero amount");

        // Use the test contract itself as receiver: it has code (receive fallback)
        // and can accept Ether, so sendTo to this address should complete
        // when c has enough balance.
        address receiver = address(this);
        uint256 cBalBefore = address(c).balance;
        uint256 recvBalBefore = receiver.balance;

        bool reverted;
        try c.sendTo(receiver, amount) {
